{
  "PROP-57888860-asm-003": {
    "property_id": "PROP-57888860-asm-003",
    "audit_result": {
      "property_id": "PROP-57888860-asm-003",
      "classification": "vulnerability",
      "code_path": "beacon-chain/execution/engine_client.go::ReconstructBlobSidecars::L641",
      "proof_trace": "ELMemPoolRequirements is empty (verification/blob.go:77), so KZG proof verification (RequireSidecarKzgProofVerified) is skipped. GetBlobsV2 path (L714) bypasses verification entirely via NewVerifiedRODataColumn. Trust assumption contradicts semi-trusted property requirement.",
      "attack_scenario": "Compromised EL sends blobs with invalid KZG proofs via GetBlobsV1/V2. CL accepts without cryptographic verification and propagates them as verified, corrupting network consensus with invalid blob data.",
      "checklist_id": "PROP-57888860-asm-003"
    },
    "text": "Engine API blob data is semi-trusted; blobs from EL must still pass KZG commitment verification.",
    "assertion": "forall blob from EL: verify_blob_kzg_proof(blob, commitment) == true before propagation",
    "covers": "SG-020",
    "severity": "MEDIUM",
    "type": "assumption"
  }
}

